// Merge all GitHub data into a single structured payload
const commits = $('Fetch Commits (7 days)').all().map(item => ({
  sha: item.json.sha?.substring(0, 7),
  message: item.json.commit?.message?.split('\n')[0],
  author: item.json.commit?.author?.name,
  date: item.json.commit?.author?.date
}));

const issues = $('Fetch Closed Issues (7 days)').all()
  .filter(item => !item.json.pull_request) // Exclude PRs from issues
  .map(item => ({
    number: item.json.number,
    title: item.json.title,
    closed_at: item.json.closed_at,
    labels: item.json.labels?.map(l => l.name)
  }));

const prs = $('Fetch Merged PRs (7 days)').all()
  .filter(item => item.json.merged_at)
  .filter(item => {
    const merged = new Date(item.json.merged_at);
    const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
    return merged >= weekAgo;
  })
  .map(item => ({
    number: item.json.number,
    title: item.json.title,
    author: item.json.user?.login,
    merged_at: item.json.merged_at,
    additions: item.json.additions,
    deletions: item.json.deletions
  }));

const repo = $vars.GITHUB_REPO || 'owner/repo';
const lang = $vars.LANGUAGE || 'EN';

return [{
  json: {
    repo,
    lang,
    period: `${new Date(Date.now() - 7*24*60*60*1000).toISOString().split('T')[0]} to ${new Date().toISOString().split('T')[0]}`,
    stats: {
      total_commits: commits.length,
      closed_issues: issues.length,
      merged_prs: prs.length
    },
    commits: commits.slice(0, 30),
    issues,
    prs
  }
}];

